DROP TABLE IF EXISTS `geo_map`;
CREATE TABLE `geo_map` (
  `geo_code` int(10) unsigned zerofill NOT NULL,
  `phcode_reg` bigint(20) DEFAULT NULL,
  `iso_reg` varchar(255) DEFAULT NULL,
  `reg_code` int(2) unsigned zerofill DEFAULT NULL,
